// === Tab: mySketch.js ===
/*  Created for #WCCChallenge "Lines"

This sketch uses a shader to render movers/shapes textured with either a buffer (which just draws lines since that is the 
prompt) or an image. I am using Lygia sdf functions.  I think you could probably do the same with build in p5.js functions, but 
I wanted to expand my shader toolkit.

AI Disclosure: I asked chatGPT how to normalize the combined sdf of all the movers;

Generative Hurricane: https://openprocessing.org/@kfahn/2921599
Coding Train Team Seas livestream: https://editor.p5js.org/codingtrain/sketches/6uE2sZROU
https://github.com/patriciogonzalezvivo/lygia/tree/main/sdf
*/

let blobShader, img;
let cnv, S, fbA, fbB;
let blob0, blob1;
let c1picker, c2picker;

const MAX_MOVERS = 50;
let movers = [];

const colors = {
	c1: [0.23, 0.31, 0.56],
	c2: [0.93, 0.44, 0.36],
};

OPC.slider({
	name: 'numMovers',
	value: 10,
	min: 1,
	max: 50,
	step: 1,
	label: 'Number of Circles',
	description: 'Number of circles'
})

OPC.slider({
	name: 'sw',
	value: 4,
	min: 1,
	max: 20,
	step: 1,
	label: 'buffer strokeweight',
	description: 'buffer strokeweight'
})

OPC.slider({
	name: 'numLines',
	value: 50,
	min: 10,
	max: 100,
	step: 1,
	label: 'Line Density',
	description: 'Number of lines'
})

OPC.slider({
	name: 'r',
	value: 0.05,
	min: 0.02,
	max: 0.2,
	step: 0.01,
	label: 'Shape radius',
	description: 'shape radius'
})

OPC.select('shapeChoice', {
	"Circle": 0,
	"Rhombus": 1,
	"Square": 2,
	"Star": 3,
	"Triangle":4,
});

OPC.toggle("useImage", false);

async function setup() {
	let S = max(windowWidth, windowHeight)
	cnv = createCanvas(windowWidth, windowHeight, WEBGL)
	// cnv = createCanvas(S, S, WEBGL);
	// cnv.position((windowWidth - width) / 2, (windowHeight - height) / 2);

	imageMode(CENTER)
	pixelDensity(1)
	noStroke();
	img = await loadImage("https://openprocessing.org/sketch/2997648/files/sky.jpg")
	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);
	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});
	gui.addColor(colors, "c1").name("Color1");
	gui.addColor(colors, "c2").name("Color2");

	fbA = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	fbB = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	fbC = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	blobShader = await createShader(resolveLygia(vert), resolveLygia(blobFrag));

	addMovers()

}

function addMovers() {
	for (let i = 0; i < numMovers; i++) {
		movers.push(new Particle(random(width), random(height)));
	}
}

function draw() {
	background(20)

	push()
	translate(-width / 2, -height / 2)
	addVerticalLines()
	addBlobShader()

	image(fbB, 0, 0)
	pop()
}

function addVerticalLines() {
	fbA.begin()
	clear()
	push()


	translate(-width / 2, -height / 2)
	background(0)

	for (let i = 0; i < numLines; i++) {
		let x = map(i, 0, numLines, 0, width);
		let y = map(i, 0, numLines, 0, height);

		addLine(x, 0, x, height)
	}

	fbA.end()
}

function addLine(x1, y1, x2, y2) {
	push()
	stroke(255)
	strokeWeight(sw)
	noFill()
	line(x1, y1, x2, y2)
	pop()
}

function addBlobShader(level) {
	fbB.begin()
	push()
	clear()

	let pos = [];
	let scale = [];

	for (let i = 0; i < numMovers; i++) {
		let mover = movers[i];
		// Pass position and scale to shader
		pos.push(mover.x, mover.y);
		scale.push(mover.scale);
		// Update each movers position
		mover.update();
	}

	blobShader.setUniform('u_resolution', [width, height]);
	blobShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	blobShader.setUniform("uCount", numMovers);
	blobShader.setUniform("u_time", millis() / 1000.0);
	if (useImage) {
		blobShader.setUniform("u_tex", img)
	} else {
		blobShader.setUniform("u_tex", fbA);
	}
	blobShader.setUniform("shapeChoice", shapeChoice);
	blobShader.setUniform("uPos", pos);
	blobShader.setUniform("r", r);
	blobShader.setUniform("col1", colors.c1);
	blobShader.setUniform("col2", colors.c2);

	shader(blobShader)

	rect(0, 0, width, height);

	pop()
	fbB.end()
}

function parameterChanged(variableName, value) {
	if (variableName === "numMovers") {
		addMovers()
	}
	if (variableName === "sw") {
		addVerticalLines()
	}
	if (variableName === "numLines") {
		addVerticalLines()
	}
}

// === Tab: shader.js ===
const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`;

const blobFrag = `#version 300 es
precision highp float;
out vec4 O;

#define MAX_MOVERS 50
uniform vec2      u_resolution; 
uniform sampler2D u_tex;
uniform vec2      uPos[MAX_MOVERS];
uniform float     r;
uniform int       uCount;
uniform vec3      col1;
uniform vec3      col2;
uniform int       shapeChoice;

#include "lygia/sdf.glsl"
#include "lygia/sdf/gearSDF.glsl"
#include "lygia/space/aspect.glsl"
#include "lygia/space/ratio.glsl"
#include "lygia/space/center.glsl"

float chooseShape(vec2 st, float radius) {
    float d;
    switch(shapeChoice){  
	     case 0:
	        d = circleSDF(st) - radius;
			  break;
	   case 1:
	        d = rhombSDF(st)- radius;
		     break;
      case 2:
	        d = rectSDF(st, vec2(0.5))- radius;
		     break; 
	   case 3:
	        d = starSDF(st, 6, radius);
		     break;
	   case 4:
	        d = triSDF(st)- radius;
		     break;
		}
    return d;
}

float addMovers(vec2 st, vec2 pixel) {
    st = ratio(st, u_resolution.xy);
    float sum = 0.0;
    float radius = r;

    for (int i = 0; i < MAX_MOVERS; i++) {
        if (i >= uCount) break;

        vec2 blob_uv = uPos[i] * pixel;

		  float d = chooseShape(st-blob_uv, radius);

        // influence syntax suggested by chatGPT
        float influence = 1.0 - smoothstep(0.0, radius, d);

        sum += influence;
    }

    return clamp(sum, 0.0, 1.0);
}

void main() {
	  vec2 pixel = 1.0/u_resolution.xy;
	  vec2 st = gl_FragCoord.xy * pixel;
	  vec4 color = texture(u_tex, st);
     st = st*0.5 + 0.5;

     float sum = addMovers(st, pixel);
	  float influence = smoothstep(0., 1.0, sum); // suggested by chatGPT

     vec3 blobTex = mix(vec3(0.0), color.rgb, influence); // black with white stripes

     vec3 finalColor = col1+col2*(blobTex.rgb);

     O = vec4(finalColor, 1.0);
}`




// === Tab: particle.js ===
class Particle {
  constructor(x,y) {
    this.x = x;
    this.y = y;
    this.vx = random(-2,2);
    this.vy = random(-2,2);
	  this.margin = 0;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    if (this.x > width-this.margin || this.x < this.margin) this.vx *= -1;
    if (this.y > height-this.margin || this.y < this.margin) this.vy *= -1;
  }


}

